}

@page "/catalog"
@using sv_e9bcdad86077426793cb0be091e1d5c9.Models
@using sv_e9bcdad86077426793cb0be091e1d5c9.Components.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
    </div>
}
else
{
    <div class="row g-3">
        <div class="col-md-3">
            <div class="border rounded bg-white">
                <CatalogFilters Categories="@_categories"
                                OnApply="HandleApplyFilters"
                                OnClear="HandleClearFilters" />
            </div>
        </div>

        <div class="col-md-9">
            @* Toolbar *@
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div>
                    <label class="form-label me-2 mb-0 d-inline" for="sortSelect">Sort by:</label>
