+@using sv_e9bcdad86077426793cb0be091e1d5c9.Components.Catalog
+@rendermode InteractiveServer
+@inject IProductService ProductService
+
+<PageTitle>Product Catalog</PageTitle>
+
+<h3 class="mb-3">Product Catalog</h3>
+
+@if (_error is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @_error
+    </div>
+}
+else
+{
+    <div class="row g-3">
+        <div class="col-md-3">
+            <div class="border rounded bg-white">
+                <CatalogFilters Categories="@_categories"
+                                OnApply="HandleApplyFilters"
+                                OnClear="HandleClearFilters" />
+            </div>
+        </div>
+
+        <div class="col-md-9">
+            @* Toolbar *@
+            <div class="d-flex justify-content-between align-items-center mb-3">
+                <div>
+                    <label class="form-label me-2 mb-0 d-inline" for="sortSelect">Sort by:</label>
+                    <select id="sortSelect" class="form-select form-select-sm d-inline-block w-auto"
+                            value="@_sortBy" @onchange="HandleSortChanged">
+                        <option value="price_asc">Price: Low to High</option>
+                        <option value="price_desc">Price: High to Low</option>
+                        <option value="name_asc">Name: A-Z</option>
+                        <option value="rating_desc">Rating: Highest</option>
+                    </select>
+                </div>
+                <div class="text-muted">
+                    @if (_result is not null && _result.TotalCount > 0)
+                    {
+                        var start = (_result.Page - 1) * _result.PageSize + 1;
+                        var end = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
+                        <span>Showing @start–@end of @_result.TotalCount products</span>
+                    }
+                </div>
+            </div>
+
+            @* Content area *@
+            @if (_loading)
+            {
+                <div class="text-center py-5">
+                    <div class="spinner-border text-primary" role="status">
+                        <span class="visually-hidden">Loading...</span>
+                    </div>
+                    <p class="mt-2 text-muted">Loading products…</p>
+                </div>
+            }
+            else if (_result is null || _result.Items.Count == 0)
+            {
+                <div class="text-center py-5">
+                    <p class="text-muted fs-5">No products found matching your criteria.</p>
+                    <button class="btn btn-outline-primary" @onclick="HandleClearFilters">Clear Filters</button>
+                </div>
+            }
+            else
+            {
+                <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3">
+                    @foreach (var product in _result.Items)
+                    {
+                        <div class="col">
+                            <ProductCard Product="@product"
+                                         OnSelected="HandleProductSelected"
+                                         OnAddToCart="HandleAddToCart" />
+                        </div>
+                    }
+                </div>
+
+                @if (TotalPages > 1)
+                {
+                    <div class="mt-4">
+                        <CatalogPagination CurrentPage="@_currentPage"
+                                           TotalPages="@TotalPages"
+                                           OnPageChanged="HandlePageChanged" />
+                    </div>
+                }
+            }
+        </div>
+    </div>
+}
+
+@code {
+    private const int PageSize = 12;
+
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    private List<string>? _categories;
+    private PagedResult<Product>? _result;
+    private ProductFilter _filter = new(null, null, null, false);
+    private string _sortBy = "price_asc";
+    private int _currentPage = 1;
+    private bool _loading = true;
+    private string? _error;
+
+    private int TotalPages => _result is null || _result.TotalCount == 0
+        ? 1
+        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            _loading = true;
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var searchTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
+            await Task.WhenAll(categoriesTask, searchTask);
+            _categories = categoriesTask.Result;
+            _result = searchTask.Result;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task SearchAsync()
+    {
+        try
+        {
+            _loading = true;
+            _error = null;
+            StateHasChanged();
+            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task HandleApplyFilters(ProductFilter filter)
+    {
+        _filter = filter;
+        _currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandleClearFilters()
+    {
+        _filter = new ProductFilter(null, null, null, false);
+        _currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandleSortChanged(ChangeEventArgs e)
+    {
+        _sortBy = e.Value?.ToString() ?? "price_asc";
+        _currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandlePageChanged(int page)
+    {
+        _currentPage = page;
+        await SearchAsync();
+    }
+
+    private async Task HandleProductSelected(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        // Placeholder for cart integration
+        return Task.CompletedTask;
+    }
+}
+

